WITH kept AS (SELECT s.* FROM customers s WHERE NOT EXISTS (SELECT 1 FROM subscriptions ch WHERE ch.customer_id = s.id AND ch.start_date >= s.signup_date)) SELECT id, name, email, segment, signup_date, credit_limit, age, CASE WHEN name RLIKE '^(Ivy Chen|Kanya Srisuk)$' THEN 'GROUP_A' WHEN name RLIKE '^(Alice Wong|bob smith)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS name_zone FROM kept ORDER BY age ASC, name_zone ASC
